from lib import *
recs=[
R(1932,"Ayam Cranberry Catalina Slow Cooker",
"Dressing Catalina dan saus cranberry berpadu menciptakan saus manis untuk merebus Ayam Cranberry Catalina Slow Cooker karya ahli diet DaVita, Jenifer dari Washington.",
["1 ekor ayam rotisserie","10 ons saus cranberry buah utuh","1/3 cangkir dressing Catalina"],
["Lepaskan daging ayam dari tulang dan kulit. Suwir lalu masukkan ke dalam slow cooker.","Tuang dressing dan saus cranberry ke atas ayam lalu aduk hingga tercampur.","Masak dengan pengaturan rendah selama 4 jam."],
["Satu ayam rotisserie rata-rata mengandung sekitar 3 cangkir daging.","Carilah ayam rotisserie dengan bumbu seminimal mungkin untuk kandungan natrium yang lebih rendah.","Untuk mengurangi natrium, ganti ayam rotisserie dengan potongan ayam mentah. Masukkan bahan-bahan dan masak dalam crockpot selama 6 hingga 8 jam pada pengaturan rendah atau 4 hingga 6 jam pada pengaturan tinggi.","Bandingkan merek dressing dan pilih yang natriumnya paling rendah.","Sajikan ayam di atas nasi jika diinginkan."],
serving="3 ons ayam, 3 sendok makan saus"),
R(1933,"Orange 7 UP®",
"Orange 7 UP® adalah cara yang lebih cerah untuk menikmati minuman bening klasik ini. Ahli diet DaVita, Sara, membagikan cara membuat minuman berwarna-warni ini dalam waktu singkat, dan ramah ginjal!",
["4 sendok teh minuman cair Kool-Aid® rasa jeruk","2 cangkir air","32 ons Diet 7 UP®"],
["Campurkan Kool-Aid® dengan 2 cangkir air. Isi cetakan es batu untuk membuat es batu rasa jeruk.","Untuk menyajikan, letakkan 2 es batu jeruk dalam gelas kecil dan tambahkan 4 ons diet 7 UP®."],
["Satu es batu kira-kira setara 1 ons cairan.","Cobalah rasa Kool-Aid favorit Anda.","Minuman cair Kool-Aid® sangat pekat dan bebas fosfat. Bubuk Kool-Aid® mengandung kalsium fosfat, yaitu zat tambahan fosfat."],
serving="6 ons"),
R(1934,"Cherry Crisp ala Traverse City",
"Seorang ahli diet DaVita dari Michigan membagikan resep Cherry Crisp ala Traverse City yang lezat dan ramah ginjal.",
["20 ons isian pai ceri kalengan","1/2 sendok teh ekstrak almond","1/2 cangkir tepung terigu putih serbaguna","1/2 cangkir gula merah, dipadatkan","1 sendok teh kayu manis bubuk","3 sendok makan mentega tanpa garam, dilunakkan","6 sendok makan topping kocok"],
["Panaskan oven terlebih dahulu hingga 350° F.","Tuang isian pai ceri ke dalam loyang 8” x 8” x 2” yang tidak diolesi minyak. Aduk bersama ekstrak almond.","Dalam mangkuk pengaduk sedang, campurkan tepung, gula merah (atau campuran gula merah Splenda®) dan kayu manis; aduk rata. Tambahkan mentega; aduk dengan garpu hingga campuran berupa remah. Taburkan campuran di atas isian pai.","Panggang selama 25 menit, atau hingga bagian atas berwarna cokelat keemasan dan isian menggelembung.","Sajikan hangat atau pada suhu ruang. Jika diinginkan, beri topping kocok."],
["Jika Anda menderita diabetes, Anda dapat mengurangi karbohidrat menjadi 34 gram dengan mengganti isian pai versi lite dan 1/4 cangkir campuran gula merah Splenda sebagai pengganti 1/2 cangkir gula merah. Hitung sebagai 2 pilihan karbohidrat. Atau, Anda dapat memperkecil porsi menjadi 1/4 cangkir.","Isian pai merek Comstock® tersedia dalam versi biasa dan lite, kalori berkurang."]),
R(1935,"Custard Oatmeal Apel Cepat dan Mudah",
"Custard Oatmeal Apel Cepat dan Mudah karya ahli diet ginjal DaVita, Maryann, adalah sarapan tinggi protein dan tinggi serat yang sempurna. Hanya butuh kurang dari 5 menit untuk menyiapkannya, sehingga cocok sebagai sarapan saat Anda sedang terburu-buru.",
["1/2 buah apel ukuran sedang","1/3 cangkir oatmeal instan","1 butir telur besar","1/2 cangkir susu almond","1/4 sendok teh kayu manis"],
["Buang bagian tengah setengah apel dan cincang halus.","Campurkan oat, telur, dan susu almond dalam mug besar. Aduk rata dengan garpu. Tambahkan kayu manis dan apel. Aduk lagi hingga tercampur sempurna.","Masak dalam microwave dengan daya tinggi selama 2 menit. Gemburkan dengan garpu. Masak 30 hingga 60 detik lagi jika perlu.","Aduk dengan sedikit susu atau air lagi jika menginginkan bubur yang lebih encer."],
["Untuk rasa tambahan, ganti kayu manis bubuk dengan batang kayu manis yang diparut halus.","Waktu memasak dapat bervariasi pada microwave yang berbeda.","Siramkan 2 sendok teh madu di atas oatmeal jika diinginkan. Hitung sebagai tambahan 12 gram karbohidrat dan 1 pilihan karbohidrat jika Anda mengikuti rencana makan penghitungan karbohidrat untuk diabetes.","Ganti susu almond dengan 1/4 cangkir susu rendah lemak 1% dan 1/4 cangkir air jika lebih disukai. Ini mengubah protein menjadi 12 gram, fosfor menjadi 278 mg, dan kalium menjadi 358 mg.","Oatmeal lebih tinggi kalium dan fosfor dibandingkan biji-bijian olahan, tetapi dapat dimasukkan dalam sebagian besar diet ginjal. Diskusikan dengan ahli diet Anda jika Anda ragu."]),
R(1937,"Bagel Salad Tuna",
"Cobalah resep ramah ginjal Bagel Salad Tuna untuk makan siang atau makan malam yang sejuk di malam yang hangat.",
["1/2 cangkir tuna kalengan rendah natrium, dikemas dalam air","1 sendok makan bawang bombai","1 sendok makan seledri","1 sendok makan mayones rendah kalori","1 buah bagel ukuran sedang 2 ons","1 lembar daun selada"],
["Pecahkan tuna menjadi potongan halus.","Cincang halus bawang bombai dan seledri.","Campurkan tuna, seledri, bawang bombai, dan mayones.","Aduk rata.","Oleskan campuran pada bagel bersama daun selada."],
["Periksa bahan tuna dan hindari merek yang menggunakan zat tambahan fosfat."]),
R(1941,"Ceviche Ikan Nila Fiesta",
"Ahli diet ginjal DaVita, Cheryl dari New York, membagikan resepnya untuk Ceviche Ikan Nila Fiesta yang ramah ginjal, hidangan utama atau pembuka yang lezat. Koktail makanan laut dingin ini menampilkan ikan nila panggang yang dilengkapi perpaduan lezat ketumbar segar, nanas, paprika merah, bawang merah, lada hitam, dan minyak zaitun. Ikan dimarinasi dalam air jeruk nipis segar dan didinginkan hingga siap disajikan, sempurna untuk menghadirkan cita rasa pesisir di meja Anda.",
["1-1/2 pon fillet ikan nila segar","1 cangkir bawang merah","1/2 cangkir paprika merah","1/4 cangkir ketumbar","1 cangkir nanas","2 sendok makan minyak canola","1/4 sendok teh lada hitam","1-1/4 cangkir air jeruk nipis segar","48 biskuit saltine dengan bagian atas tanpa garam"],
["Cincang bawang merah, paprika, dan ketumbar. Potong dadu nanas. Potong ikan nila menjadi potongan kecil.","Panggang potongan ikan nila dengan broiler suhu tinggi selama 3 menit per sisi.","Dinginkan ikan nila selama 5 menit lalu tuang air jeruk nipis segar di atasnya dan aduk rata. Pastikan semua potongan ikan nila terendam sepenuhnya dalam air jeruk nipis.","Campurkan paprika, bawang merah, ketumbar, nanas, lada hitam, dan minyak canola dengan ikan nila yang telah matang.","Tutup dan simpan di lemari es untuk dimarinasi setidaknya 2 jam.","Sajikan setiap porsi dengan 6 biskuit saltine dengan bagian atas tanpa garam."],
["Sebagai hidangan pembuka, sajikan dalam gelas martini dengan 1/4 cangkir ceviche dan hias dengan biskuit saltine dengan bagian atas tanpa garam serta beberapa lembar daun ketumbar.","Satu buah jeruk nipis menghasilkan 2 sendok makan air jeruk nipis. Resep ini membutuhkan sepuluh buah jeruk nipis.","Ganti dengan potongan nanas kecil kalengan dalam sari buah jika nanas segar tidak tersedia."],
serving="1 cangkir plus 6 biskuit"),
R(1943,"Paprika Isi ala Barat Daya",
"Paprika, yang penuh vitamin C dan antioksidan, juga umum digunakan, dan kedua jenis paprika mendapat “peran utama” dalam resep ramah ginjal yang dipersembahkan ahli diet DaVita, Odila dari Texas: Paprika Isi ala Barat Daya.",
["4 buah paprika merah","1 sendok makan minyak canola","1/2 cangkir bawang bombai, dicincang","1 pon daging sapi giling tanpa lemak","1 sendok teh bubuk bawang putih","1/2 sendok teh jintan bubuk","1/2 sendok teh oregano kering (remas di telapak tangan)","1 cangkir biji jagung beku","10 ons kaleng Rotel® Original Diced Tomatoes & Green Chilies"],
["Panaskan oven terlebih dahulu hingga 350°F.","Potong bagian atas setiap paprika merah. Buang biji dan tangkainya.","Rebus sebentar paprika selama sekitar 4 menit.","Dalam wajan besar, panaskan minyak canola dan tumis bawang bombai hingga bening.","Masukkan daging sapi giling dan aduk agar terpisah-pisah.","Tambahkan bubuk bawang putih, jintan, dan oregano kering ke dalam campuran daging.","Tambahkan jagung dan tomat kalengan dengan cabai. Aduk ke dalam campuran daging.","Tegakkan paprika dalam loyang 2 kuart. Isi dengan campuran daging, tambahkan sisa isian ke dalam loyang.","Tutup dan panggang selama 40 menit."],
["Jika Anda ingin rasa yang kurang pedas, tambahkan versi ringan dari tomat kalengan dengan cabai.","Pastikan dihitung sebagai 2 porsi sayuran jika Anda menjalani diet rendah kalium. Untuk mengurangi kalium menjadi 534 mg, tambahkan 1-1/2 cangkir nasi matang, hilangkan jagung, dan kurangi tomat kalengan dengan cabai menjadi 1/2 cangkir.","Pasien yang menjalani dialisis peritoneal atau hemodialisis di rumah setiap hari sering kali membutuhkan asupan kalium yang lebih tinggi. Resep ini dapat membantu menyediakan lebih banyak kalium.","Untuk diet PGK non-dialisis berprotein lebih rendah, kurangi daging sapi giling menjadi 1/2 pon dari jumlah yang dianjurkan oleh ahli diet Anda."],
serving="1 paprika isi"),
R(1944,"Bagel dengan Telur dan Salmon",
"Bagel dengan Telur dan Salmon adalah cara cepat dan mudah untuk memadukan sisa salmon dengan bagel dan telur favorit Anda.",
["1/2 buah bagel","1 sendok makan krim keju","1 sendok makan daun bawang","1/2 sendok teh dill segar","2 lembar daun basil segar","1 iris tomat","4 lembar arugula","1 butir telur besar","1 ons salmon matang"],
["Belah bagel menjadi dua dan panggang satu belahan dalam pemanggang roti atau oven.","Cincang daun bawang, dill, dan daun basil. Campurkan dengan krim keju.","Oleskan campuran krim keju pada belahan bagel yang telah dipanggang lalu taruh arugula dan irisan tomat di atasnya.","Panaskan wajan, semprot dengan semprotan antilengket dan buat telur orak-arik.","Panaskan kembali salmon di wajan yang sama saat telur dimasak.","Letakkan telur dan salmon di atas irisan tomat. Selamat menikmati!"],
["Ini cara yang bagus untuk menghabiskan sisa salmon sehari setelah dimasak.","Pilihan bagel meliputi plain, telur, gandum hitam (rye), pumpernickel, bawang, atau gandum.","Analisis nutrisi didasarkan pada 1/2 bagel seberat 4 ons. Untuk sandwich rendah karbohidrat, pilih bagel seberat 2 ons.","Arugula dapat diganti dengan daun bayam segar, selada, atau microgreens."],
serving="1/2 bagel dengan 1 telur dan 1 ons salmon"),
R(1946,"Salad Nasi dan Sayuran Creamy",
"Baik Anda berada di dalam rumah maupun bersiap piknik, ahli diet DaVita, Mary, punya resep ramah ginjal yang pasti Anda sukai: salad nasi dan sayuran creamy.",
["1 cangkir beras, mentah","2 cangkir seledri","1 buah bawang merah ukuran sedang","1/4 cangkir paprika merah","1 buah mentimun kecil","8 buah lobak ukuran sedang","1-1/4 cangkir mayones","4 sendok teh mustard siap pakai","4 butir telur besar rebus matang"],
["Masak nasi (atau pasta) sesuai petunjuk kemasan tanpa tambahan garam. Dinginkan di lemari es.","Iris seledri dan cincang halus bawang merah dan paprika. Kupas dan potong dadu mentimun serta iris lobak. Cincang telur.","Tambahkan mayones, seledri, bawang, dan mustard ke dalam nasi atau pasta yang telah dingin. Aduk rata dan simpan di lemari es hingga siap disajikan.","Aduk telur, irisan lobak, mentimun, dan paprika merah sebelum menyajikan salad dingin."],
["Pilih nasi atau pasta salad (elbow, shell mini, makaroni salad). Keduanya cocok untuk salad yang luar biasa ini.","Kurangi mayones atau gunakan mayones bebas lemak untuk hidangan yang lebih rendah lemak.","Dua batang seledri ukuran sedang menghasilkan sekitar 1 cangkir seledri iris, bawang ukuran sedang berdiameter sekitar 2-1/2″, 1 mentimun kecil panjangnya 6-7″, dan lobak ukuran sedang berdiameter sekitar 1″.","Satu paprika merah besar menghasilkan 1 cangkir cincang. Saat menyiapkan resep ini, sisa paprika dapat diiris dan dijadikan camilan."]),
R(1947,"Kentang Goreng Ubi Jalar Tipis dengan Jintan",
"Kentang tidak selalu terlarang dalam diet ginjal. Ahli diet DaVita, Nicole, membagikan metode perendamannya untuk menurunkan kalium pada ubi jalar atau kentang putih. Nikmati Kentang Goreng Ubi Jalar Tipis dengan Jintan ini.",
["2 buah ubi jalar ukuran sedang","1 sendok teh minyak zaitun","1 sendok teh jintan bubuk","1/4 sendok teh lada hitam","1/8 sendok teh garam"],
["Kupas ubi jalar dan potong menjadi irisan tipis panjang 1/4 inci. Rendam ubi jalar pada suhu ruang semalaman, buang airnya setidaknya sekali dan isi ulang setidaknya sekali.","Panaskan oven terlebih dahulu hingga 425° F.","Tiriskan dan keringkan potongan ubi jalar lalu masukkan ke dalam kantong berzip. Tambahkan minyak zaitun, garam, lada, dan jintan lalu kocok hingga terbalut rata.","Letakkan kentang di atas loyang. Panggang selama 20 menit atau hingga tingkat kerenyahan yang diinginkan."],
["Mengupas dan mengiris ubi jalar sebelum direndam akan memperluas permukaan ubi jalar dan meningkatkan pelepasan kalium. Lewati langkah ini jika Anda tidak memerlukan diet rendah kalium."],
serving="1/4 resep"),
R(1949,"Salad Tuna Apel Tarragon dengan Kenari",
"Apel dan kenari meningkatkan salad tuna biasa dengan menambahkan bahan yang meningkatkan nutrisi dan antioksidan. Salad Tuna Apel Tarragon dengan Kenari adalah salah satu variasi dari resep Salad Tuna Serbaguna karya ahli diet DaVita, Jessica.",
["1 buah apel ukuran sedang","1 batang seledri","1/4 cangkir bawang bombai","1 sendok makan minyak zaitun extra-virgin","15 ons tuna putih, kalengan dalam air, tanpa garam","1/2 cangkir mayones","1 sendok makan tarragon segar cincang halus","2 sendok teh air perasan lemon","1/2 sendok teh gula pasir (opsional)","1/4 cangkir kenari cincang"],
["Buang bagian tengah apel dan cincang. Cincang halus seledri dan bawang bombai. Masukkan bawang bombai dan minyak zaitun ke dalam mangkuk kecil yang aman untuk microwave dan panaskan dalam microwave selama 2 menit. Biarkan dingin beberapa menit.","Tiriskan tuna dengan baik dan masukkan ke dalam mangkuk pengaduk. Tepuk dengan tisu dapur untuk menghilangkan kelebihan air.","Aduk seledri, campuran bawang bombai, mayones, tarragon, air perasan lemon, dan gula. Aduk hingga tercampur rata.","Tambahkan apel cincang dan kenari lalu aduk hingga tercampur.","Dinginkan di lemari es sebelum disajikan."],
["Sajikan di atas daun selada, dalam wrap, atau dengan roti stik atau biskuit rendah natrium.","Jika tarragon segar tidak tersedia, ganti dengan basil segar atau peterseli.","Gunakan mayones rendah lemak untuk mengurangi lemak menjadi 17 gram. Perhatikan bahwa kandungan natrium akan lebih tinggi."]),
R(1950,"Paha Ayam Crock-Pot® dengan Glasir Nanas",
"Ahli diet ginjal DaVita, Kristy dari Kansas, memiliki hidangan utama ramah ginjal yang mudah dibuat dan cocok untuk Anda. Paha Ayam Crock-pot® dengan Glasir Nanas mengubah ayam dari biasa menjadi luar biasa dengan saus asam manis dari perpaduan menggoda jus nanas, lada hitam, gula merah, dan kecap asin rendah natrium.",
["1-1/2 pon paha ayam tanpa tulang dan tanpa kulit","1/2 sendok teh lada hitam","1/2 sendok teh bubuk bawang putih","2 sendok makan minyak zaitun","20 ons nanas potongan kecil kalengan dalam jus tanpa pemanis","2 sendok makan gula merah, dipadatkan","2 sendok makan kecap asin rendah natrium","1/2 sendok teh saus Tabasco®","2 sendok makan tepung maizena","3 sendok makan air","4 sendok makan daun bawang","3 cangkir nasi matang"],
["Taburkan lada dan bubuk bawang putih pada kedua sisi paha ayam.","Panaskan minyak dalam wajan besar dengan api sedang-besar. Masukkan ayam ke wajan dan masak 2-3 menit di setiap sisi, hingga kecokelatan.","Pindahkan ayam ke dalam crock pot® 4 kuart yang telah diolesi semprotan masak.","Tiriskan jus nanas ke dalam gelas ukur. Jika kurang dari 1 cangkir, tambahkan air hingga menjadi 1 cangkir. Aduk jus ke dalam sisa cairan di wajan, dan kerok untuk melepaskan sisa kecokelatan ayam. Angkat dari api, lalu aduk bersama gula merah, kecap asin, dan saus Tabasco. Tambahkan 1 cangkir potongan nanas. Tuang campuran ke atas paha ayam dalam crock pot. Tutup dan masak dengan pengaturan api rendah selama 3 jam.","Angkat ayam dari crock pot dan ubah ke pengaturan api tinggi. Campurkan tepung maizena dan 3 sendok makan air dalam mangkuk kecil. Aduk ke dalam saus di crock pot. Masak 2 menit atau hingga saus mengental, sambil terus diaduk dengan whisk. Tambahkan daun bawang dan aduk hingga terbalut.","Sajikan setiap paha ayam di atas 1/2 cangkir nasi."],
["Saus mungkin tidak mengental di Crock-pot jika suhunya tidak cukup tinggi. Jika belum mengental setelah 2-3 menit, tuang saus ke dalam panci saus dan panaskan dengan api sedang, sambil diaduk hingga mengental. Masukkan kembali ke crock-pot bersama ayam dan nanas.","Ukuran dan berat paha ayam bervariasi. Kami membuat resep ini menggunakan kemasan 1-1/2 pon berisi enam paha ayam tanpa tulang dan tanpa kulit, masing-masing sekitar 4 ons dalam keadaan mentah. Untuk diet rendah protein, potong paha ayam menjadi dua (2 ons) atau gunakan paha yang lebih kecil jika tersedia.","Akan tersisa sekitar 1 cangkir potongan nanas. Makan sebagai camilan atau hidangan penutup keesokan harinya atau coba resep nanas lainnya."],
serving="1 paha ayam dengan 1/3 cangkir saus di atas 1/2 cangkir nasi"),
R(1954,"Salsa Nanas Panggang",
"Buat Salsa Nanas Panggang ini untuk pesta Anda. Resep DaVita lezat, ramah ginjal, dan dikirimkan oleh ahli diet DaVita.",
["5 iris nanas kalengan","1 buah pir segar kecil","1/2 buah paprika merah","2 iris bawang merah"],
["Tiriskan irisan nanas. Cuci pir dan potong menjadi irisan bulan. Cuci paprika dan potong memanjang. Panaskan wajan grill dengan api sedang.","Semprot wajan grill dengan semprotan masak dan letakkan buah dan sayuran di dalamnya. (Anda mungkin perlu memasaknya dalam dua kali.) Masak sekitar 5 menit per sisi, hingga sedikit kecokelatan.","Masukkan nanas, pir, paprika, dan bawang yang telah dimasak ke dalam food processor atau blender. Pulse hingga tercincang kasar.","Diamkan salsa di lemari es semalaman."],
["Sajikan dengan biskuit rendah natrium atau keripik tortilla. Carilah merek dengan kandungan natrium terendah.","Anda juga dapat menyajikannya dengan keripik pita buatan sendiri. Belah roti pita menjadi dua dan potong setiap belahan menjadi empat bagian. Semprot dengan semprotan masak dan panggang dalam oven 350º F selama sekitar 8 menit.","Tiriskan salsa dengan saringan halus untuk membuang cairan jika Anda menjalani pembatasan cairan.","Jika diinginkan, gunakan nanas segar sebagai pengganti nanas kalengan."]),
R(1956,"Meatloaf Khas Amerika",
"Joyce, ahli diet DaVita dari Michigan, membagikan keahlian gizinya dan resep favorit khas Amerika sepanjang masa untuk Meatloaf Khas Amerika yang ramah ginjal.",
["2 sendok makan bawang bombai","20 keping biskuit tipe saltine, bagian atas tanpa garam","1 pon daging sapi giling tanpa lemak (10% lemak)","1 butir telur besar","2 sendok makan susu rendah lemak 1%","1/4 sendok teh lada hitam","1/3 cangkir saus tomat","1 sendok makan gula merah","1/2 sendok teh cuka sari apel","1 sendok teh air"],
["Panaskan oven terlebih dahulu hingga 350° F.","Cincang halus bawang bombai. Masukkan biskuit ke dalam kantong berzip besar dan hancurkan dengan rolling pin.","Olesi loyang roti dengan semprotan masak antilengket.","Dalam mangkuk besar, campurkan biskuit hancur, bawang bombai, daging sapi giling, telur, susu, dan lada hitam. Aduk rata.","Masukkan campuran ke dalam loyang roti. Panggang selama 40 menit.","Untuk membuat topping, campurkan saus tomat, gula merah, cuka, dan air dalam mangkuk kecil.","Keluarkan meatloaf yang telah matang dari oven dan lapisi dengan saus.","Masukkan kembali loyang ke dalam oven dan panggang selama 10 menit atau hingga suhu bagian dalam mencapai 160° F.","Potong menjadi 6 porsi dan sajikan."],
["Gunakan sisa meatloaf untuk membuat sandwich.","Agar lebih ramah diabetes, pastikan menggunakan daging paling tanpa lemak, 7-10% lemak. Ini akan mengurangi lemak jenuh. Atau makan dalam porsi lebih kecil."],
serving="1/6 potong meatloaf"),
R(1959,"Sandwich Steak Kembang Kol",
"Steak kembang kol adalah hidangan populer, dan mengubahnya menjadi sandwich adalah ide makanan yang bagus. Dengan berbagai pilihan pelengkap, hidangan ini bisa berbeda setiap kali Anda membuatnya. Ahli diet ginjal Jackie dari Virginia memilih menggunakan selada, bawang, mustard, dan mayones untuk resep ini. Selamat mencoba kombinasi baru.",
["1 kepala kembang kol ukuran sedang","3 sendok makan minyak zaitun","1/4 sendok teh bubuk bawang putih","1/4 sendok teh bubuk bawang bombai","1/8 sendok teh garam","1/4 sendok teh lada","1/4 cangkir bawang merah","4 lembar daun selada","2 sendok makan plus 2 sendok teh mayones","4 sendok teh mustard","4 roti hamburger"],
["Panaskan oven terlebih dahulu hingga 400˚ F. Alasi loyang panggang dengan kertas roti.","Buang daun kembang kol dan potong bagian bawah batangnya. Belah kepala kembang kol menjadi dua. Potong setiap belahan menjadi irisan 1” hingga 3/4”, dengan bagian inti tetap utuh. Potong bagian ujung yang lebih kecil dan simpan untuk resep lain. Seharusnya ada 4 steak kembang kol.","Campurkan minyak zaitun, bubuk bawang putih, bubuk bawang bombai, garam, dan lada.","Letakkan kembang kol di atas loyang beralas kertas roti. Gunakan setengah campuran minyak zaitun untuk mengoleskan pada steak. Masukkan ke dalam oven yang telah dipanaskan selama 20 menit. Keluarkan dari oven dan balik steak. Olesi steak dengan sisa minyak zaitun dan panggang sekitar 20 menit lagi, hingga kecokelatan keemasan di bagian tepi.","Iris bawang merah. Letakkan setiap steak di atas separuh roti hamburger, oleskan dengan 2 sendok teh mayones, 1 sendok teh mustard, beberapa irisan bawang merah, daun selada, dan separuh roti hamburger lainnya."],
["Sisa kembang kol dapat digunakan dalam omelet, dipotong kecil-kecil untuk direbus sebagai pengganti nasi, atau dimakan mentah dengan saus celup dari krim asam dan Mrs. Dash®.","Ganti roti dengan pita, croissant, atau sourdough.","Cobalah topping lain seperti irisan mentimun, irisan paprika hijau, atau mustard Dijon."]),
]
save(2,recs)
